-- PT105-S4-Q14. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT105-S4-Q14$batch04$ AND q.stimulus=$batch04$Citizen: Our legislators need to act quickly to counter the effects of the recession, especially the present level of unemployment, which is the highest ever. We urgently need a major tax cut for our upper-income citizens. There would then be a correspondingly large increase in investment that would create new jobs. If this measure is not taken, investment will not grow.$batch04$ AND q.prompt=$batch04$The citizen's argument depends on the assumption that$batch04$ AND q.correct_choice=$batch04$D$batch04$) THEN RAISE EXCEPTION 'Question changed: PT105-S4-Q14'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch04$352458de-28ad-43f0-a977-cf5751c9f621$batch04$) <> 4 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch04$352458de-28ad-43f0-a977-cf5751c9f621$batch04$) <> 3 THEN RAISE EXCEPTION 'Explanation changed: PT105-S4-Q14'; END IF; END $guard$;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$C$batch04$, $batch04$The argument is about whether this tax cut would make upper-income citizens invest. How their past investment compares with lower-income citizens' does not matter. Negate it and nothing changes.$batch04$), ($batch04$E$batch04$, $batch04$The citizen predicts what this tax cut will do. It does not need past tax cuts to have worked. Negate it, "past tax cuts did not tend to create jobs," and this one still could.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT105-S4-Q14$batch04$ AND e.id=$batch04$352458de-28ad-43f0-a977-cf5751c9f621$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
